bounded_host_request.command:
set -eu
img=create-videobot:native-sticker-c8c50d4
docker image inspect "$img" >/dev/null 2>&1 || { echo CANDIDATE_IMAGE_MISSING; exit 81; }
docker run --rm --network none --pull never --entrypoint grep "$img" -q 'ステッカー・絵文字' /opt/videobot/src/telegram/menuPanel.mjs || { echo CANDIDATE_HOME_MENU_MISSING; exit 82; }
docker run --rm --network none --pull never --entrypoint grep "$img" -q 'there is no text in the message to edit' /opt/videobot/src/telegram/creatorScreenTransport.mjs || { echo CANDIDATE_RECOVERY_PATCH_MISSING; exit 83; }
docker run --rm --network none --pull never --entrypoint node "$img" -e "import('./src/runtime/creatorPollingMain.mjs').then(()=>process.exit(0)).catch(()=>process.exit(1))" >/dev/null || { echo CANDIDATE_IMPORT_FAILED; exit 84; }
echo CANDIDATE_IMAGE_VALID=PASS
